1	<script lang="ts">
2		/**
3		 * Expenses Page
4		 *
5		 * Implements expense categorization feature defined in:
6		 * specs/specifications/expense-categorization.md
7		 * specs/specifications/expense-date-filter.md
8		 *
9		 * Traceable to:
10		 * - #{#exp1a} - Expenses Tab Navigation (IMPLEMENTED)
11		 * - #{#exp1b} - Expenses derived from receipts (IMPLEMENTED)
12		 * - #{#exp9a} - Expense table layout with sorting and selection (IMPLEMENTED)
13		 * - #{#exp6a} - Uncategorized queue view (IMPLEMENTED)
14		 * - #{#exp7a} - Category filter and analytics (IMPLEMENTED)
15		 * - #{#exr1a} - Click expense row to open receipt edit modal (IMPLEMENTED)
16		 * - #{#exr1b} - Integrate existing ReceiptEditModal component (IMPLEMENTED)
17		 * - #{#exr2a} - Make expense rows clickable (IMPLEMENTED)
18		 * - #{#exr2b} - Preserve expenses state after edit (IMPLEMENTED)
19		 * - #{#exp1a} - CSV Export Button (IMPLEMENTED)
20		 * - #{#exp1b} - Respect Current Date Filter (IMPLEMENTED)
21		 * - #{#exp4b} - Integration with Expenses Page (IMPLEMENTED)
22		 * - #{#edf1a} - Expenses View URL Date Filter Integration (IMPLEMENTED)
23		 * - #{#edf4a} - URL Parameter Validation (IMPLEMENTED)
24		 *
25		 * Future enhancements will include:
26		 * - #{#exp2a} - Category assignment UI (partial implementation with CategoryDropdown)
27		 * - #{#exp6b} - Bulk category assignment (UI ready, backend needed)
28		 */
29	
30		import { onMount, untrack } from 'svelte';
31		import { SvelteURLSearchParams } from 'svelte/reactivity';
32		import { page } from '$app/stores';
33		import { goto, replaceState } from '$app/navigation';
34		import { resolve } from '$app/paths';
35		import { supabase } from '$lib/supabaseClient';
36		import { getSignedReceiptUrl, getSignedReceiptUrls } from '$lib/utils/signedUrl';
37		import { ExpenseService, type Expense } from '$lib/services/ExpenseService';
38		import { CategoryService } from '$lib/services/CategoryService';
39		import { ReceiptService } from '$lib/services/ReceiptService';
40		import { CSVExportService } from '$lib/services/CSVExportService';
41		import { PDFExportService } from '$lib/services/PDFExportService';
42		import {
43			readDateFilter,
44			matchesDateRange,
45			applyDateFilterParams,
46			clearDateFilterParams
47		} from '$lib/utils/sharedDateFilter';
48		import { formatDate } from '$lib/utils/dateConversion';
49		import { formatCurrencyWithEstimate } from '$lib/utils/formatCurrency';
50		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
51		import { resolveCategory, buildCategoryMap, findCategoryById } from '$lib/utils/resolveCategory';
52		import { shouldEnablePDFExport } from '$lib/utils/pdfExportState';
53		import { DEFAULT_CATEGORY_COLOR, type Category } from '$lib/types/Category';
54		import type { CategoryGroup } from '$lib/types/Hierarchy';
55		import type { Session } from '@supabase/supabase-js';
56		import type { ReceiptRow } from '$lib/models/Receipt';
57		import CategoryDropdown from '$lib/components/CategoryDropdown.svelte';
58		import ReceiptEditModal from '$lib/components/ReceiptEditModal.svelte';
59		import FilterPanel from '$lib/components/FilterPanel.svelte';
60		import FilteredEmptyState from '$lib/components/FilteredEmptyState.svelte';
61		import Notification from '$lib/components/Notification.svelte';
62		import DataTable from '$lib/components/DataTable.svelte';
63		import { emptySelection } from '$lib/utils/selectionModel';
64	
65		const receiptService = new ReceiptService(supabase);
66	
67		let session: Session | null = $state(null);
68		let familyId: string | null = $state(null);
69		let expenses: Expense[] = $state([]);
70		let categories: Category[] = $state([]);
71		// Spending-hierarchy Groupings, offered when creating a new category inline so
72		// it can be filed straight away rather than landing in Uncategorized.
73		let groups: CategoryGroup[] = $state([]);
74		// #{#rf09} Resolve each row's Category once per (expenses, categories) change
75		// instead of an O(rows × categories) find() per table render.
76		let categoryByReceipt = $derived(buildCategoryMap(expenses, categories));
77		let loading = $state(true);
78		let error: string | null = $state(null);
79		let expenseSelection = $state(emptySelection());
80		let isDeleting = $state(false);
81	
82		// #{#exp6a} - Uncategorized filter state
83		let showUncategorizedOnly = $state(false);
84	
85		// #{#exp7a} - Category filter state
86		let selectedCategoryIds: string[] = $state([]);
87	
88		// #{#edf1a} - URL-based date filter state (read from query parameters)
89		let urlDateFilter = $derived(readDateFilter($page.url.searchParams));
90		let urlDateFrom = $derived(urlDateFilter.dateFrom);
91		let urlDateTo = $derived(urlDateFilter.dateTo);
92	
93		// #{#edf1a} - Temporary date filter inputs (before "Apply" is clicked)
94		let tempFilterDateFrom = $state('');
95		let tempFilterDateTo = $state('');
96	
97		// #{#edf1a} - Sync temp values when URL changes
98		$effect(() => {
99			tempFilterDateFrom = urlDateFrom;
100			tempFilterDateTo = urlDateTo;
101		});
102	
103		// #{#exr1b} - Receipt edit modal state
104		let editingReceipt: ReceiptRow | null = $state(null);
105		let editingExpense: Expense | null = $state(null);
106		let showEditModal = $state(false);
107		let isSaving = $state(false);
108		let successMessage: string | null = $state(null);
109	
110		// #{#exp1a} #{#exp3b} - CSV Export state
111		let isExporting = $state(false);
112		const csvService = new CSVExportService();
113	
114		// #{#cre1a} #{#cre4a} - PDF Export state
115		let isExportingPDF = $state(false);
116		let pdfExportProgress = $state('');
117		let pdfAbortController: AbortController | null = $state(null);
118		const pdfService = new PDFExportService();
119	
120		onMount(async () => {
121			// #{#exp1a} Criterion 7: Verify authentication
122			const { data } = await supabase.auth.getSession();
123			session = data.session;
124	
125			if (!session) {
126				return;
127			}
128	
129			// Get user's default family
130			familyId = await getDefaultFamilyId();
131	
132			if (!familyId) {
133				error = 'No family found. Please contact support.';
134				return;
135			}
136	
137			// #{#exp1b} Load expenses derived from receipts
138			await loadExpenses();
139	
140			// Load family categories for dropdown
141			await loadCategories();
142	
143			// #{#vca5a} Check for auto-categorization matches on page load
144			await checkForAutoCategorizationMatches();
145		});
146	
147		/**
148		 * Load expenses from receipts using ExpenseService
149		 * #{#exp1b} - Expenses derived from receipts
150		 */
151		async function loadExpenses() {
152			if (!session?.user) return;
153	
154			try {
155				loading = true;
156				error = null;
157	
158				const expenseService = new ExpenseService(supabase);
159				expenses = await expenseService.getExpenses(session.user.id);
160			} catch (err) {
161				console.error('Error loading expenses:', err);
162				error = err instanceof Error ? err.message : 'Failed to load expenses';
163			} finally {
164				loading = false;
165			}
166		}
167	
168		// #{#exp6b} Selection-based bulk delete. An expense IS a receipt (1:1, computed),
169		// so this deletes the underlying receipts (record + stored file).
170		async function deleteSelected(): Promise<void> {
171			const receiptIds = Array.from(expenseSelection.selected);
172			if (receiptIds.length === 0) return;
173			if (
174				!confirm(
175					`Delete ${receiptIds.length} selected expense${receiptIds.length === 1 ? '' : 's'}? This removes the underlying receipt and its stored file.`
176				)
177			) {
178				return;
179			}
180	
181			isDeleting = true;
182			error = null;
183			const originalExpenses = expenses;
184			// Optimistic update — remove from UI immediately
185			expenses = expenses.filter((e) => !expenseSelection.selected.has(e.receipt_id));
186	
187			try {
188				await receiptService.bulkDeleteReceipts(receiptIds);
189				expenseSelection = emptySelection();
190				showToast(
191					`Deleted ${receiptIds.length} expense${receiptIds.length === 1 ? '' : 's'}`,
192					'success'
193				);
194			} catch (err) {
195				// Rollback on failure
196				expenses = originalExpenses;
197				error = err instanceof Error ? err.message : 'Failed to delete expenses';
198			} finally {
199				isDeleting = false;
200			}
201		}
202	
203		/**
204		 * Check for and apply vendor rule matches to uncategorized expenses
205		 * #{#vca5a} - Batch Auto-Categorization on Page Load
206		 */
207		async function checkForAutoCategorizationMatches() {
208			if (!familyId) return;
209	
210			try {
211				const expenseService = new ExpenseService(supabase);
212	
213				// Apply all family vendor rules to current expenses
214				const totalAssigned = await expenseService.applyAllVendorRules(familyId, expenses);
215	
216				// If any expenses were auto-assigned, reload and notify user
217				if (totalAssigned > 0) {
218					await loadExpenses();
219					showToast(
220						`Auto-categorized ${totalAssigned} expense${totalAssigned === 1 ? '' : 's'} based on vendor rules`,
221						'success'
222					);
223				}
224			} catch (err) {
225				console.error('Error checking auto-categorization:', err);
226				// Don't show error to user - this is a background operation
227			}
228		}
229	
230		/**
231		 * Load family categories for dropdown
232		 * #{#exp2a} - Category Assignment UI
233		 * #{#exp3a} - Auto-initialize default categories for new families
234		 */
235		async function loadCategories() {
236			if (!familyId) return;
237	
238			try {
239				const categoryService = new CategoryService(supabase);
240				categories = await categoryService.getFamilyCategories(familyId);
241	
242				// Auto-initialize default categories for families with no categories
243				// #{#exp3a} Requirement 2 & 3
244				if (categories.length === 0) {
245					await categoryService.createDefaultCategories(familyId);
246					categories = await categoryService.getFamilyCategories(familyId);
247				}
248	
249				// Groupings power the "Group" selector in inline category creation.
250				// Best-effort: a family without a seeded hierarchy simply gets no
251				// selector (the feature degrades to the previous behaviour).
252				groups = await categoryService.getFamilyGroups(familyId);
253			} catch (err) {
254				console.error('Error loading categories:', err);
255			}
256		}
257	
258		/**
259		 * Handle category assignment
260		 * #{#exp2a} - Category Assignment UI
261		 * #{#exp5b} - Manual Override Precedence
262		 * #{#exp5a} - Auto-create vendor rules on first categorization
263		 */
264		async function handleCategorySelect(receiptId: string, category: Category) {
265			try {
266				const expenseService = new ExpenseService(supabase);
267	
268				// 1. Assign category to this expense
269				await expenseService.assignCategory(receiptId, category.id, 'manual');
270	
271				// 2. Auto-create vendor rule if none exists
272				// Find the expense to get merchant_name
273				const expense = expenses.find((e) => e.receipt_id === receiptId);
274				if (expense && familyId) {
275					// Check if rule already exists
276					const existingRule = await expenseService.getVendorRule(familyId, expense.merchant_name);
277	
278					// Only create rule if none exists (silent auto-creation)
279					if (!existingRule) {
280						await expenseService.createVendorRule(familyId, expense.merchant_name, category.id);
281	
282						// #{#vca1a} Apply rule to visible expenses after creating it
283						const vendorPattern = expenseService.normalizeVendor(expense.merchant_name);
284						const appliedCount = await expenseService.applyRuleToVisibleExpenses(
285							filteredExpenses,
286							vendorPattern,
287							category.id
288						);
289	
290						// #{#vca3a} Show user feedback if expenses were auto-assigned
291						if (appliedCount > 0) {
292							showToast(
293								`Applied ${category.name} to ${appliedCount} matching expense${appliedCount === 1 ? '' : 's'}`,
294								'success'
295							);
296						}
297					}
298					// If rule exists, user must click "change default" in dropdown to update it
299				}
300	
301				// 3. Reload expenses to reflect the change
302				await loadExpenses();
303			} catch (err) {
304				console.error('Error assigning category:', err);
305				error = err instanceof Error ? err.message : 'Failed to assign category';
306			}
307		}
308	
309		/**
310		 * Handle inline category creation from CategoryDropdown
311		 * #{#exp3b} - Create New Category Inline
312		 */
313		async function handleCreateNewCategory(data: {
314			name: string;
315			color: string | null;
316			groupId: string | null;
317		}) {
318			try {
319				const categoryService = new CategoryService(supabase);
320				await categoryService.createCategory(
321					familyId || '',
322					data.name,
323					data.color || undefined,
324					data.groupId
325				);
326				await loadCategories();
327				showToast(`Created category: ${data.name}`, 'success');
328			} catch (err) {
329				console.error('Error creating category:', err);
330				showToast(err instanceof Error ? err.message : 'Failed to create category', 'error');
331			}
332		}
333	
334		/**
335		 * Handle vendor rule creation from CategoryDropdown
336		 * #{#vca1a} - Apply rules to visible expenses when rule is created/updated
337		 * #{#vca3a} - Show user feedback for auto-assignment
338		 */
339		async function handleVendorRuleCreated(data: { merchantName: string; categoryId: string }) {
340			try {
341				const { merchantName, categoryId } = data;
342				const expenseService = new ExpenseService(supabase);
343	
344				// Get category name for feedback
345				const category = findCategoryById(categories, categoryId);
346				if (!category) return;
347	
348				// Apply rule to visible expenses
349				const vendorPattern = expenseService.normalizeVendor(merchantName);
350				const appliedCount = await expenseService.applyRuleToVisibleExpenses(
351					filteredExpenses,
352					vendorPattern,
353					categoryId
354				);
355	
356				// Show user feedback
357				if (appliedCount > 0) {
358					showToast(
359						`Applied ${category.name} to ${appliedCount} matching expense${appliedCount === 1 ? '' : 's'}`,
360						'success'
361					);
362				}
363	
364				// Reload expenses to reflect the changes
365				await loadExpenses();
366			} catch (err) {
367				console.error('Error applying vendor rule:', err);
368				error = err instanceof Error ? err.message : 'Failed to apply vendor rule';
369			}
370		}
371	
372		// formatCurrency imported from $lib/utils/formatCurrency
373	
374		// formatDate imported from $lib/utils/dateConversion
375	
376		/**
377		 * #{#exp6a} Criterion 2: Filter uncategorized expenses
378		 * #{#exp7a} Criterion 2 & 4: Filter by category (OR logic for multiple)
379		 * #{#edf1a} Criterion 6 & 8: Filter by date range from URL (works with category filters)
380		 */
381		let filteredExpenses = $derived(
382			expenses.filter((expense) => {
383				// #{#edf1a} Date range filter (from URL parameters)
384				if (!matchesDateRange(expense.transaction_date, urlDateFrom, urlDateTo)) {
385					return false;
386				}
387	
388				// #{#exp6a} Uncategorized filter takes precedence
389				if (showUncategorizedOnly) {
390					return expense.category_id === null;
391				}
392	
393				// #{#exp7a} Category filter (OR logic)
394				if (selectedCategoryIds.length > 0) {
395					return expense.category_id && selectedCategoryIds.includes(expense.category_id);
396				}
397	
398				// No filters active, show all
399				return true;
400			})
401		);
402	
403		/**
404		 * #{#exp6a} Criterion 3: Count uncategorized expenses
405		 * #{#flt1a} Use filteredExpenses to reflect current filter state
406		 */
407		let uncategorizedCount = $derived(filteredExpenses.filter((e) => e.category_id === null).length);
408	
409		/**
410		 * #{#exp7a} Criterion 3: Count expenses per category
411		 * #{#flt1a} Use filteredExpenses to reflect current filter state
412		 */
413		let expenseCountByCategory = $derived(
414			filteredExpenses.reduce(
415				(acc, expense) => {
416					const key = expense.category_id || 'uncategorized';
417					acc[key] = (acc[key] || 0) + 1;
418					return acc;
419				},
420				{} as Record<string, number>
421			)
422		);
423	
424		/**
425		 * #{#cre1a} #{#cre1b} #{#cre4a} PDF export button state
426		 * RF-13: pure predicate lives in $lib/utils/pdfExportState
427		 */
428		let pdfExportEnabled = $derived(
429			shouldEnablePDFExport({
430				filteredExpensesCount: filteredExpenses.length,
431				selectedCategoryIds,
432				showUncategorizedOnly,
433				isExporting: isExportingPDF
434			})
435		);
436	
437		/**
438		 * #{#exp6a} Criterion 1 & 5: Toggle uncategorized filter
439		 */
440		function toggleUncategorizedFilter() {
441			showUncategorizedOnly = !showUncategorizedOnly;
442			// Clear category filter when showing uncategorized
443			if (showUncategorizedOnly) {
444				selectedCategoryIds = [];
445			}
446			updateURL();
447		}
448	
449		/**
450		 * #{#exp7a} Toggle category selection
451		 */
452		function toggleCategoryFilter(categoryId: string) {
453			if (selectedCategoryIds.includes(categoryId)) {
454				selectedCategoryIds = selectedCategoryIds.filter((id) => id !== categoryId);
455			} else {
456				selectedCategoryIds = [...selectedCategoryIds, categoryId];
457			}
458			// Clear uncategorized filter when selecting categories
459			if (selectedCategoryIds.length > 0) {
460				showUncategorizedOnly = false;
461			}
462			updateURL();
463		}
464	
465		/**
466		 * #{#exp7a} Clear all category filters
467		 */
468		function clearCategoryFilter() {
469			selectedCategoryIds = [];
470			updateURL();
471		}
472	
473		/**
474		 * #{#edf1a} Criterion 2: Apply date filters to URL
475		 */
476		function applyFilterValues(): void {
477			const params = applyDateFilterParams(
478				$page.url.searchParams,
479				tempFilterDateFrom,
480				tempFilterDateTo
481			);
482			goto(resolve(`/expenses?${params.toString()}`), { replaceState: true, keepFocus: true });
483		}
484	
485		/**
486		 * #{#edf1a} Criterion 3: Clear all filters (date + category)
487		 */
488		function clearClientFilters(): void {
489			// Clear URL date filters
490			const params = clearDateFilterParams($page.url.searchParams);
491			goto(resolve(`/expenses?${params.toString()}`), { replaceState: true, keepFocus: true });
492	
493			// Reset temp date filter inputs
494			tempFilterDateFrom = '';
495			tempFilterDateTo = '';
496	
497			// Clear category filters
498			showUncategorizedOnly = false;
499			selectedCategoryIds = [];
500			updateURL();
501		}
502	
503		/**
504		 * #{#exp6a} Criterion 7 & #{#exp7a}: Update URL with filter state
505		 */
506		function updateURL() {
507			const params = new SvelteURLSearchParams();
508	
509			if (showUncategorizedOnly) {
510				params.set('filter', 'uncategorized');
511			} else if (selectedCategoryIds.length > 0) {
512				params.set('category', selectedCategoryIds.join(','));
513			}
514	
515			const query = params.toString();
516			replaceState(query ? resolve(`/expenses?${query}`) : resolve('/expenses'), {});
517		}
518	
519		/**
520		 * #{#exp6a} Criterion 7 & #{#exp7a}: Restore filter state from URL on mount
521		 */
522		onMount(() => {
523			const params = new URLSearchParams(window.location.search);
524			const filter = params.get('filter');
525			const category = params.get('category');
526	
527			if (filter === 'uncategorized') {
528				showUncategorizedOnly = true;
529			} else if (category) {
530				selectedCategoryIds = category.split(',');
531			}
532		});
533	
534		/**
535		 * #{#exr1a} Open receipt edit modal when clicking expense row
536		 * #{#exr1b} Convert Expense to ReceiptRow format for modal
537		 */
538		function openReceiptEditModal(expense: Expense) {
539			editingExpense = expense;
540			editingReceipt = {
541				id: expense.receipt_id,
542				user_id: session?.user?.id || '',
543				merchant_name: expense.merchant_name,
544				transaction_date: expense.transaction_date,
545				total_amount: expense.total_amount,
546				receipt_image_path: expense.receipt_image_path ?? null,
547				tax: null,
548				currency: expense.currency,
549				exchange_rate_to_cad: expense.exchange_rate_to_cad,
550				credit_card_name: null,
551				credit_card_last_4: null,
552				created_at: new Date().toISOString(),
553				matched_transaction_id: null,
554				suspicious_date: false,
555				original_filename: null // #{#ofn1a} display-only; not carried on Expense
556			};
557			showEditModal = true;
558		}
559	
560		/**
561		 * #{#exr1b} Handle receipt save event from modal
562		 * #{#exr2b} Preserve state by reloading expenses without changing filters
563		 */
564		async function handleReceiptSave(updatedReceipt: ReceiptRow) {
565			isSaving = true;
566			error = null;
567	
568			try {
569				await receiptService.update(updatedReceipt.id, {
570					merchant_name: updatedReceipt.merchant_name,
571					transaction_date: updatedReceipt.transaction_date,
572					total_amount: updatedReceipt.total_amount,
573					tax: updatedReceipt.tax,
574					currency: updatedReceipt.currency,
575					exchange_rate_to_cad: updatedReceipt.exchange_rate_to_cad,
576					credit_card_name: updatedReceipt.credit_card_name,
577					credit_card_last_4: updatedReceipt.credit_card_last_4,
578					receipt_image_path: updatedReceipt.receipt_image_path,
579					matched_transaction_id: updatedReceipt.matched_transaction_id,
580					suspicious_date: updatedReceipt.suspicious_date
581				});
582	
583				showEditModal = false;
584				editingReceipt = null;
585				editingExpense = null;
586	
587				// #{#exr2b} Reload expenses to show updated data
588				await loadExpenses();
589	
590				// Show success message
591				successMessage = 'Receipt updated successfully';
592				setTimeout(() => {
593					successMessage = null;
594				}, 3000);
595			} catch (err) {
596				error = err instanceof Error ? err.message : 'Failed to update receipt';
597			} finally {
598				isSaving = false;
599			}
600		}
601	
602		/**
603		 * #{#exr1b} Handle modal close event
604		 */
605		function handleModalClose() {
606			showEditModal = false;
607			editingReceipt = null;
608			editingExpense = null;
609			error = null;
610		}
611	
612		/**
613		 * #{#exp1a} #{#exp4b} Handle CSV export
614		 * #{#exp1b} Respects current filter (exports filteredExpenses)
615		 * #{#exp3b} Shows loading state and feedback
616		 * #{#edf2a} CSV export respects date filters and includes date range in filename
617		 */
618		async function handleExportCSV() {
619			// #{#exp1a} Criterion 3: Disabled when no expenses
620			if (filteredExpenses.length === 0) {
621				return;
622			}
623	
624			isExporting = true;
625			try {
626				// #{#exp4b} Criterion 2: Export filtered expenses
627				const csvContent = csvService.exportExpensesToCSV(filteredExpenses);
628	
