644				showToast(
645					`CSV exported successfully: ${filteredExpenses.length} expense${filteredExpenses.length !== 1 ? 's' : ''}`,
646					'success'
647				);
648			} catch (err) {
649				// #{#exp3b} Criterion 4: Error feedback
650				console.error('Error exporting CSV:', err);
651				showToast(
652					`Failed to export CSV: ${err instanceof Error ? err.message : 'Unknown error'}`,
