660		/**
661		 * #{#cre1a} #{#cre4b} Handle PDF receipt export
662		 * #{#cre1b} Respects current filters (exports filteredExpenses)
663		 * #{#cre4a} Shows progress and supports cancellation
664		 */
665		async function handleExportPDF() {
666			if (!pdfExportEnabled) return;
667	
668			isExportingPDF = true;
669			pdfExportProgress = 'Preparing receipt data...';
670			pdfAbortController = new AbortController();
671	
672			try {
673				// #{#cre1b} Build category names for the selected filters
674				const selectedCategories = categories.filter((c) => selectedCategoryIds.includes(c.id));
675				const categoryNames = selectedCategories.map((c) => c.name);
676	
677				// #{#cre3a} Fetch receipt images via signed URLs
678				const fetchImageFn = async (path: string): Promise<Uint8Array | null> => {
679					const signedUrl = await getSignedReceiptUrl(path, 300); // 5 min expiry
680					if (!signedUrl) return null;
681					const response = await fetch(signedUrl);
682					if (!response.ok) return null;
683					const buffer = await response.arrayBuffer();
684					return new Uint8Array(buffer);
685				};
686	
687				// #{#cre1b} Build date range from URL filters
688				const dateRange =
689					urlDateFrom && urlDateTo
690						? { start: urlDateFrom, end: urlDateTo }
691						: urlDateFrom
692							? { start: urlDateFrom, end: urlDateFrom }
693							: null;
694	
695				const pdfBytes = await pdfService.generateReceiptPDF(filteredExpenses, {
696					categories: selectedCategories,
697					dateRange,
698					fetchImageFn,
699					abortSignal: pdfAbortController.signal,
700					onProgress: (step: string) => {
701						pdfExportProgress = step;
702					}
703				});
704	
705				// #{#cre3b} Generate filename and download
706				const filename = pdfService.generateFilename(categoryNames, dateRange);
707				pdfService.downloadPDF(pdfBytes, filename);
708	
709				// #{#cre4a} Success feedback
710				const totalAmount = pdfService.calculateSubtotal(filteredExpenses);
711				showToast(
712					`PDF exported: ${filteredExpenses.length} receipt${filteredExpenses.length !== 1 ? 's' : ''} across ${categoryNames.length} categor${categoryNames.length !== 1 ? 'ies' : 'y'}, ${pdfService.formatAmount(totalAmount)} total`,
713					'success'
714				);
715			} catch (err) {
716				if (err instanceof Error && /abort|cancel/i.test(err.message)) {
717					showToast('PDF export cancelled', 'success');
718				} else {
719					console.error('Error exporting PDF:', err);
720					showToast(
721						`Failed to generate PDF: ${err instanceof Error ? err.message : 'Unknown error'}`,
722						'error'
723					);
724				}
725			} finally {
726				isExportingPDF = false;
727				pdfExportProgress = '';
728				pdfAbortController = null;
729			}
730		}
