732		/**
733		 * Show toast notification
734		 * #{#exp3b} Criterion 3, 4: Success/error feedback
735		 */
736		function showToast(message: string, type: 'success' | 'error') {
737			successMessage = message;
738			setTimeout(
739				() => {
740					successMessage = null;
741				},
742				type === 'success' ? 3000 : 5000
743			);
744		}
