746		// #{#sec1a} Signed URL cache for receipt images
747		let signedUrls: Record<string, string> = $state({});
748	
749		// #{#sec1a} Load signed URLs whenever expenses change
750		// Uses untrack to read signedUrls without creating a reactive loop
751		$effect(() => {
752			const paths = expenses.map((e) => e.receipt_image_path).filter((p): p is string => !!p);
753			untrack(() => loadSignedUrls(paths));
754		});
755	
756		async function loadSignedUrls(paths: string[]) {
757			const cached = signedUrls;
758			const newUrls: Record<string, string> = {};
759			const missing: string[] = [];
760			for (const path of paths) {
761				if (cached[path]) newUrls[path] = cached[path];
762				else missing.push(path);
763			}
764			// #{#sec1c} Sign all uncached paths in one batched request instead of one per path.
765			if (missing.length > 0) {
766				Object.assign(newUrls, await getSignedReceiptUrls(missing));
767			}
768			signedUrls = newUrls;
769		}
770	
771		function getImageUrl(path: string | null): string | null {
772			if (!path) return null;
773			return signedUrls[path] ?? null;
774		}
