1	<script module lang="ts">
2		import type { Snippet } from 'svelte';
3	
4		export interface Column<Row> {
5			key: string;
6			header: string;
7			align?: 'left' | 'center' | 'right';
8			/** Present ⇒ column is sortable; the accessor returns the value to sort by. */
9			sortValue?: (row: Row) => string | number;
10			/** Cell has its own controls; a click inside it must not open the row. */
11			interactive?: boolean;
12			cell: Snippet<[Row]>;
13		}
14	</script>
15	
16	<script lang="ts" generics="Row">
17		// Shared list-page table shell (RF-03). Owns the responsive container, the
18		// sortable header (one consistent accessible indicator), sort state + sorting,
19		// the selection column with modifier-aware multi-select, and the empty-state
20		// branching. Per-row content, row-click editing and the empty message are
21		// supplied by the calling page via snippets, so the domain differences
22		// (thumbnail, category dropdown, badges, actions) stay page-side.
23		import { nextSortState, sortRows, type SortState } from '$lib/utils/tableSort';
24		import {
25			applySelectionClick,
26			emptySelection,
27			isAllSelected,
28			isIndeterminate,
29			toggleSelectAll,
30			type SelectionState
31		} from '$lib/utils/selectionModel';
32	
33		function alignClass(align?: 'left' | 'center' | 'right'): string {
34			if (align === 'right') return 'text-right';
35			if (align === 'center') return 'text-center';
36			return 'text-left';
37		}
38	
39		let {
40			rows,
41			columns,
42			getRowId,
43			selectable = false,
44			selection = $bindable(emptySelection()),
45			onRowClick,
46			initialSort,
47			rowClass,
48			empty
49		}: {
50			rows: Row[];
51			columns: Column<Row>[];
52			getRowId: (row: Row) => string;
53			selectable?: boolean;
54			selection?: SelectionState;
55			onRowClick?: (row: Row) => void;
56			initialSort?: SortState;
57			/** Extra classes per row (e.g. duplicate / selected highlighting). */
58			rowClass?: (row: Row) => string;
59			empty: Snippet;
60		} = $props();
61	
62		// initialSort seeds the starting sort only; header clicks own it afterwards.
63		// svelte-ignore state_referenced_locally
64		let sort = $state<SortState | null>(initialSort ?? null);
65	
66		const activeColumn = $derived(sort ? columns.find((c) => c.key === sort!.key) : undefined);
67		const sortedRows = $derived(
68			activeColumn?.sortValue ? sortRows(rows, activeColumn.sortValue, sort!.direction) : rows
69		);
70		const orderedIds = $derived(sortedRows.map(getRowId));
71	
72		const totalColumns = $derived(columns.length + (selectable ? 1 : 0));
73	
74		function ariaSort(col: Column<Row>): 'ascending' | 'descending' | 'none' {
75			if (!col.sortValue || sort?.key !== col.key) return 'none';
76			return sort!.direction === 'asc' ? 'ascending' : 'descending';
77		}
78	
79		function onHeaderClick(col: Column<Row>) {
80			if (!col.sortValue) return;
81			sort = nextSortState(sort, col.key);
82		}
83	
84		// We don't preventDefault the native toggle: doing so triggers the browser's
85		// canceled-activation, which reverts `checked` after Svelte set it and leaves the
86		// box visually out of sync. Instead we let it toggle, then force it to match state
87		// (state wins — a Shift-range can leave the clicked row's own value unchanged).
88		function onRowCheckbox(event: MouseEvent, row: Row) {
89			const id = getRowId(row);
90			selection = applySelectionClick(orderedIds, selection, id, {
91				shiftKey: event.shiftKey,
92				toggleKey: event.metaKey || event.ctrlKey
93			});
94			(event.currentTarget as HTMLInputElement).checked = selection.selected.has(id);
95		}
96	
97		function onSelectAll(event: MouseEvent) {
98			selection = toggleSelectAll(orderedIds, selection);
99			(event.currentTarget as HTMLInputElement).checked = isAllSelected(
100				orderedIds,
101				selection.selected
102			);
103		}
104	</script>
105	
106	<!-- Scroll horizontally on small screens; stay `overflow: visible` on desktop so an
107	     in-row dropdown (e.g. the expenses category picker) is not clipped. -->
108	<div class="overflow-x-auto rounded border sm:overflow-visible">
109		<table class="min-w-full text-sm">
110			<thead class="bg-gray-50">
111				<tr>
112					{#if selectable}
113						<th class="px-3 py-2 text-left">
114							<input
115								type="checkbox"
116								checked={isAllSelected(orderedIds, selection.selected)}
117								indeterminate={isIndeterminate(orderedIds, selection.selected)}
118								onclick={onSelectAll}
119								aria-label="Select all"
120								class="h-4 w-4 rounded border-gray-300"
121							/>
122						</th>
123					{/if}
124					{#each columns as col (col.key)}
125						{#if col.sortValue}
126							<th
127								class="cursor-pointer px-3 py-2 hover:bg-gray-100 {alignClass(col.align)}"
128								onclick={() => onHeaderClick(col)}
129								onkeydown={(e) => (e.key === 'Enter' || e.key === ' ') && onHeaderClick(col)}
130								role="columnheader"
131								tabindex="0"
132								aria-sort={ariaSort(col)}
133							>
134								{col.header}
135								{#if sort?.key === col.key}
136									<span class="ml-1">{sort.direction === 'asc' ? '↑' : '↓'}</span>
137								{/if}
138							</th>
139						{:else}
140							<th class="px-3 py-2 {alignClass(col.align)}">
141								{col.header}
142							</th>
143						{/if}
144					{/each}
145				</tr>
146			</thead>
147			<tbody class="divide-y divide-gray-200">
148				{#if sortedRows.length === 0}
149					<tr>
150						<td colspan={totalColumns} class="px-3 py-8 text-center">
151							{@render empty()}
152						</td>
153					</tr>
154				{:else}
155					{#each sortedRows as row (getRowId(row))}
156						<!-- Row-open lives on each non-interactive cell (delegation-safe), not
157						     on the <tr> with a target guard. Interactive cells simply omit it. -->
158						<tr
159							class="{onRowClick ? 'cursor-pointer hover:bg-gray-50' : ''} {rowClass?.(row) ?? ''}"
160							onkeydown={(e) => e.key === 'Enter' && onRowClick?.(row)}
161							role={onRowClick ? 'button' : undefined}
162							tabindex={onRowClick ? 0 : undefined}
163						>
164							{#if selectable}
165								<td class="px-3 py-2">
166									<input
167										type="checkbox"
168										checked={selection.selected.has(getRowId(row))}
169										onclick={(e) => onRowCheckbox(e, row)}
170										aria-label="Select row"
171										class="h-4 w-4 rounded border-gray-300"
172									/>
173								</td>
174							{/if}
175							{#each columns as col (col.key)}
176								<td
177									class="px-3 py-2 {alignClass(col.align)}"
178									onclick={() => {
179										if (!col.interactive) onRowClick?.(row);
180									}}
181								>
182									{@render col.cell(row)}
183								</td>
184							{/each}
185						</tr>
186					{/each}
187				{/if}
188			</tbody>
189		</table>
190	</div>
