1	/**
2	 * ExpenseService
3	 *
4	 * Service for managing expenses derived from receipts
5	 * Specification: #{#exp1b} - Expenses Derived from Receipts
6	 * Authority: system
7	 * Priority: Critical
8	 *
9	 * Key Principles:
10	 * - Expenses are computed views, not separate database entities
11	 * - Each receipt generates exactly one expense (1:1 mapping)
12	 * - Deleting a receipt automatically removes the expense (CASCADE)
13	 * - Creating a receipt automatically makes it available as an expense
14	 */
15	
16	import type { SupabaseClient } from '@supabase/supabase-js';
17	
18	/**
19	 * Expense data structure derived from receipts
20	 * #{#umf1b} - Extended with matched_transaction_id for unmatched filter
21	 */
22	export interface Expense {
23		receipt_id: string;
24		merchant_name: string;
25		total_amount: number | null; // null when OCR could not read the receipt amount
26		transaction_date: string;
27		receipt_image_path?: string;
28		category_id: string | null;
29		categorization_source: 'manual' | 'auto' | null;
30		category_name?: string | null;
31		category_color?: string | null;
32		matched_transaction_id: string | null; // #{#umf1b} - Match status for reconciliation
33		currency: string | null; // #{#fcr4a} - Original currency for display
34		exchange_rate_to_cad: number | null; // #{#fcr4a} - Bank of Canada rate for estimated CAD
35	}
36	
37	/**
38	 * Filter options for querying expenses
39	 */
40	export interface ExpenseFilters {
41		startDate?: string;
42		endDate?: string;
43		categoryId?: string;
44		merchantName?: string;
45	}
46	
47	/**
48	 * Shape of a receipts row as returned by the expense query, including the
49	 * embedded expense_categories -> categories join (1:1 per receipt).
50	 */
51	interface ExpenseReceiptRow {
52		id: string;
53		merchant_name: string;
54		total_amount: number | null; // receipts.total_amount is nullable (OCR may fail)
55		transaction_date: string;
56		receipt_image_path?: string;
57		matched_transaction_id: string | null;
58		currency: string | null;
59		exchange_rate_to_cad: number | null;
60		expense_categories: {
61			category_id: string | null;
62			categorization_source: 'manual' | 'auto' | null;
63			categories: {
64				name: string | null;
65				color: string | null;
66			} | null;
67		} | null;
68	}
69	
70	/**
71	 * Re-shapes a PostgREST embedded-join result to its real runtime shape.
72	 *
73	 * The untyped client infers to-one embeds (`expense_categories`, `categories`) as
74	 * arrays, but a 1:1 relationship returns a single object (or null) at runtime. This
75	 * names the single boundary where we bridge the inferred type to the runtime shape,
76	 * so the coercion isn't re-asserted with an `as unknown as` at each call site.
77	 */
78	function coerceEmbed<T>(value: unknown): T {
79		return value as T;
80	}
81	
82	/**
83	 * ExpenseService Class
84	 * Handles all expense-related operations
85	 */
86	export class ExpenseService {
87		private supabase: SupabaseClient;
88	
89		constructor(supabase: SupabaseClient) {
90			this.supabase = supabase;
91		}
92	
93		/**
94		 * Get expenses for a user (derived from receipts)
95		 *
96		 * @param userId - User ID to filter expenses
97		 * @param filters - Optional filters (date range, category, merchant)
98		 * @returns Array of expenses
99		 *
100		 * Specification: #{#exp1b} Requirements 1, 2, 3, 7
101		 */
102		async getExpenses(userId: string, filters?: ExpenseFilters): Promise<Expense[]> {
103			// Requirement: User ID validation
104			if (!userId) {
105				throw new Error('User ID is required');
106			}
107	
108			const rows = await this.fetchAllReceiptRows(filters);
109			const expenses = rows.map((receipt) => this.mapReceiptRowToExpense(receipt));
110	
111			return this.applyCategoryFilter(expenses, filters);
112		}
113	
114		/**
115		 * Fetch every receipt row matching the filters, paging past PostgREST's
116		 * per-request row cap (1000 by default).
117		 *
118		 * Without paging, a family with more than 1000 receipts only ever sees the
119		 * newest 1000: the Spending-report drill-down into an older year lands on an
120		 * empty Expenses list ("hiding all 1000 expenses"), and the report itself
121		 * undercounts any year that exceeds the cap. This became reachable once the
122		 * historical-expense importer could add thousands of receipts at once.
123		 */
124		private async fetchAllReceiptRows(filters?: ExpenseFilters): Promise<ExpenseReceiptRow[]> {
125			const PAGE_SIZE = 1000;
126			const all: ExpenseReceiptRow[] = [];
127	
128			for (let from = 0; ; from += PAGE_SIZE) {
129				const { data, error } = await this.buildExpenseQuery(filters).range(
130					from,
131					from + PAGE_SIZE - 1
132				);
133				if (error) {
134					throw new Error(error.message);
135				}
136	
137				const batch = coerceEmbed<ExpenseReceiptRow[]>(data ?? []);
138				all.push(...batch);
139	
140				// A short page means we've reached the end.
141				if (batch.length < PAGE_SIZE) break;
142			}
143	
144			return all;
145		}
146	
147		/**
148		 * Build the receipts query that computes the expense view: receipts joined
149		 * with expense_categories and categories, with SQL-level filters and the
150		 * default sort applied.
151		 *
152		 * #{#umf1b} - Includes matched_transaction_id to support the unmatched filter.
153		 * Don't filter by user_id - let RLS policies handle access based on family membership.
154		 */
155		private buildExpenseQuery(filters?: ExpenseFilters) {
156			let query = this.supabase.from('receipts').select(
157				`
158					id,
159					merchant_name,
160					total_amount,
161					transaction_date,
162					receipt_image_path,
163					matched_transaction_id,
164					currency,
165					exchange_rate_to_cad,
166					expense_categories (
167						category_id,
168						categorization_source,
169						categories (
170							name,
171							color
172						)
173					)
174				`
175			);
176	
177			if (filters?.startDate) {
178				query = query.gte('transaction_date', filters.startDate);
179			}
180	
181			if (filters?.endDate) {
182				query = query.lte('transaction_date', filters.endDate);
183			}
184	
185			if (filters?.merchantName) {
186				query = query.ilike('merchant_name', `%${filters.merchantName}%`);
187			}
188	
189			// Default sort: transaction_date descending (newest first)
190			return query.order('transaction_date', { ascending: false });
191		}
192	
193		/**
194		 * Transform one database row into an Expense object.
195		 * Handles the 1:1 mapping: each receipt → one expense.
196		 * #{#umf1b} - Includes matched_transaction_id in the transformation.
197		 */
198		private mapReceiptRowToExpense(receipt: ExpenseReceiptRow): Expense {
199			const expenseCategory = receipt.expense_categories;
200			const category = expenseCategory?.categories;
201	
202			return {
203				receipt_id: receipt.id,
204				merchant_name: receipt.merchant_name,
205				total_amount: receipt.total_amount,
206				transaction_date: receipt.transaction_date,
207				receipt_image_path: receipt.receipt_image_path,
208				category_id: expenseCategory?.category_id || null,
209				categorization_source: expenseCategory?.categorization_source || null,
210				category_name: category?.name || null,
211				category_color: category?.color || null,
212				matched_transaction_id: receipt.matched_transaction_id || null,
213				currency: receipt.currency || null,
214				exchange_rate_to_cad: receipt.exchange_rate_to_cad ?? null
215			};
216		}
217	
218		/**
219		 * Apply the category filter after transformation.
220		 * Note: For better performance, this could be moved to the SQL query
221		 * but current schema makes it complex due to LEFT JOIN structure.
222		 */
223		private applyCategoryFilter(expenses: Expense[], filters?: ExpenseFilters): Expense[] {
224			if (!filters?.categoryId) {
225				return expenses;
226			}
227	
228			return expenses.filter((expense) => expense.category_id === filters.categoryId);
229		}
230	
231		/**
232		 * Assign a category to an expense (receipt)
233		 *
234		 * @param receiptId - Receipt ID to categorize
235		 * @param categoryId - Category ID to assign
236		 * @param source - Source of categorization ('manual' or 'auto')
237		 *
238		 * Specification: #{#exp5b} - Manual Override Precedence
239		 */
240		async assignCategory(
241			receiptId: string,
242			categoryId: string,
243			source: 'manual' | 'auto' = 'manual'
244		): Promise<void> {
245			if (!receiptId) {
246				throw new Error('Receipt ID is required');
247			}
248	
249			if (!categoryId) {
250				throw new Error('Category ID is required');
251			}
252	
253			// Insert or update expense category
254			// Manual assignments always override auto assignments
255			const { error } = await this.supabase.from('expense_categories').upsert(
256				{
257					receipt_id: receiptId,
258					category_id: categoryId,
259					categorization_source: source,
260					updated_at: new Date().toISOString()
261				},
262				{
263					onConflict: 'receipt_id'
264				}
265			);
266	
267			if (error) {
268				throw new Error(error.message);
269			}
270		}
271	
272		/**
273		 * Bulk assign category to multiple expenses
274		 *
275		 * @param receiptIds - Array of receipt IDs
276		 * @param categoryId - Category ID to assign
277		 * @param source - Categorization source ('manual' or 'auto'), defaults to 'manual'
278		 *
279		 * Specification: #{#exp6b} - Bulk Category Assignment
280		 * Updated: #{#vca1a} - Support auto-assignment source
281		 */
282		async bulkAssignCategory(
283			receiptIds: string[],
284			categoryId: string,
285			source: 'manual' | 'auto' = 'manual'
286		): Promise<void> {
287			if (!receiptIds || receiptIds.length === 0) {
288				throw new Error('Receipt IDs are required');
289			}
290	
291			if (!categoryId) {
292				throw new Error('Category ID is required');
293			}
294	
295			// Create batch update records
296			const updates = receiptIds.map((receiptId) => ({
297				receipt_id: receiptId,
298				category_id: categoryId,
299				categorization_source: source,
300				updated_at: new Date().toISOString()
301			}));
302	
303			// Batch upsert
304			const { error } = await this.supabase.from('expense_categories').upsert(updates, {
305				onConflict: 'receipt_id'
306			});
307	
308			if (error) {
309				throw new Error(error.message);
310			}
311		}
312	
313		/**
314		 * Normalize vendor name for pattern matching
315		 *
316		 * @param merchantName - Raw merchant name
317		 * @returns Normalized pattern
318		 *
319		 * Specification: #{#exp4a} - Vendor Normalization
320		 */
321		normalizeVendor(merchantName: string): string {
322			return merchantName
323				.toLowerCase()
324				.trim()
325				.replace(/[^a-z0-9\s]/g, '') // Remove special chars
326				.replace(/\s+/g, ' '); // Normalize whitespace
327		}
328	
329		/**
330		 * Get existing vendor rule for a merchant
331		 *
332		 * @param familyId - Family ID
333		 * @param merchantName - Merchant name to look up
334		 * @returns Vendor rule with category info, or null if not found
335		 *
336		 * Specification: #{#exp5a} - Vendor Rule Management (Family-scoped)
337		 */
338		async getVendorRule(
339			familyId: string,
340			merchantName: string
341		): Promise<{ category_id: string; category_name: string } | null> {
342			if (!familyId || !merchantName) {
343				return null;
344			}
345	
346			const vendorPattern = this.normalizeVendor(merchantName);
347	
348			const { data, error } = await this.supabase
349				.from('vendor_category_rules')
350				.select('category_id, categories(name)')
351				.eq('family_id', familyId)
352				.eq('vendor_pattern', vendorPattern)
353				.single();
354	
355			if (error || !data) {
356				return null;
357			}
358	
359			const categories = coerceEmbed<{ name: string } | null>(data.categories);
360	
361			return {
362				category_id: data.category_id,
363				category_name: categories?.name || 'Unknown'
364			};
365		}
366	
367		/**
368		 * Create vendor category rule
369		 *
370		 * @param familyId - Family ID
371		 * @param merchantName - Merchant name to match
372		 * @param categoryId - Category to assign
373		 *
374		 * Specification: #{#exp4a} - Automatic Category Assignment via Vendor Rules (Family-scoped)
375		 */
376		async createVendorRule(
377			familyId: string,
378			merchantName: string,
379			categoryId: string
380		): Promise<void> {
381			if (!familyId || !merchantName || !categoryId) {
382				throw new Error('Family ID, merchant name, and category ID are required');
383			}
384	
385			const vendorPattern = this.normalizeVendor(merchantName);
386	
387			const { error } = await this.supabase.from('vendor_category_rules').upsert(
388				{
389					family_id: familyId,
390					vendor_pattern: vendorPattern,
391					category_id: categoryId,
392					updated_at: new Date().toISOString()
393				},
394				{
395					onConflict: 'family_id,vendor_pattern'
396				}
397			);
398	
399			if (error) {
400				throw new Error(error.message);
401			}
402		}
