404		/**
405		 * Apply vendor category rule to visible expenses
406		 *
407		 * @param expenses - Currently visible expenses in UI
408		 * @param vendorPattern - Normalized vendor pattern to match
409		 * @param categoryId - Category ID to assign
410		 * @returns Number of expenses that were auto-assigned
411		 *
412		 * Specification: #{#vca1a} - Apply Rules to Visible Expenses on Creation
413		 */
414		async applyRuleToVisibleExpenses(
415			expenses: Expense[],
416			vendorPattern: string,
417			categoryId: string
418		): Promise<number> {
419			// Filter for uncategorized expenses that match the vendor pattern
420			const matchingExpenses = expenses.filter((expense) => {
421				// Only process uncategorized expenses
422				if (expense.category_id !== null) {
423					return false;
424				}
425	
426				// Skip if merchant_name is null or empty
427				if (!expense.merchant_name) {
428					return false;
429				}
430	
431				// Normalize and compare
432				const normalizedMerchant = this.normalizeVendor(expense.merchant_name);
433				return normalizedMerchant === vendorPattern;
434			});
435	
436			// If no matches, return early
437			if (matchingExpenses.length === 0) {
438				return 0;
439			}
440	
441			// Extract receipt IDs
442			const receiptIds = matchingExpenses.map((e) => e.receipt_id);
443	
444			// Bulk assign with source='auto'
445			await this.bulkAssignCategory(receiptIds, categoryId, 'auto');
446	
447			return matchingExpenses.length;
448		}
449	
450		/**
451		 * Apply all vendor category rules to expenses
452		 *
453		 * @param familyId - Family ID whose rules to apply
454		 * @param expenses - Array of expenses to check
455		 * @returns Number of expenses that were auto-assigned
456		 *
457		 * Specification: #{#vca5a} - Batch Auto-Categorization on Page Load (Family-scoped)
458		 */
459		async applyAllVendorRules(familyId: string, expenses: Expense[]): Promise<number> {
460			// Return early if no expenses
461			if (!expenses || expenses.length === 0) {
462				return 0;
463			}
464	
465			// Fetch all vendor rules for this family
466			const { data: vendorRules, error } = await this.supabase
467				.from('vendor_category_rules')
468				.select('vendor_pattern, category_id')
469				.eq('family_id', familyId);
470	
471			if (error) {
472				throw new Error(error.message);
473			}
474	
475			// Return early if no rules exist
476			if (!vendorRules || vendorRules.length === 0) {
477				return 0;
478			}
479	
480			// Apply each rule and track total assignments
481			let totalAssigned = 0;
482	
483			for (const rule of vendorRules) {
484				const count = await this.applyRuleToVisibleExpenses(
485					expenses,
486					rule.vendor_pattern,
487					rule.category_id
488				);
489				totalAssigned += count;
490			}
491	
492			return totalAssigned;
493		}
494	}
