1	/**
2	 * Pure multi-select state machine shared by the list-page tables (RF-03).
3	 *
4	 * The tables drive selection from a row checkbox with modifier keys. Plain
5	 * row-click is reserved for editing, so all selection intent arrives here as a
6	 * checkbox click carrying the Shift / Cmd-or-Ctrl state. Keeping this logic pure
7	 * (ordered ids + state + click -> state) lets the fiddly range/anchor rules be
8	 * unit-tested without a browser or component.
9	 */
10	
11	export interface SelectionClick {
12		/** Shift held: extend the anchor -> row range. */
13		shiftKey: boolean;
14		/** Cmd (mac) or Ctrl (win/linux) held: additive toggle. */
15		toggleKey: boolean;
16	}
17	
18	export interface SelectionState {
19		selected: Set<string>;
20		/** Last row whose checkbox was clicked without Shift; origin of a Shift range. */
21		anchorId: string | null;
22	}
23	
24	/** An empty selection (nothing selected, no anchor). */
25	export function emptySelection(): SelectionState {
26		return { selected: new Set(), anchorId: null };
27	}
28	
29	/** Apply a checkbox click to the selection, returning a fresh state. */
30	export function applySelectionClick(
31		orderedIds: string[],
32		state: SelectionState,
33		id: string,
34		mods: SelectionClick
35	): SelectionState {
36		// Shift extends the anchor -> row range when there is a still-visible anchor;
37		// otherwise it degrades to a plain toggle.
38		if (mods.shiftKey && state.anchorId !== null) {
39			const anchorIdx = orderedIds.indexOf(state.anchorId);
40			const targetIdx = orderedIds.indexOf(id);
41			if (anchorIdx !== -1 && targetIdx !== -1) {
42				const [lo, hi] = anchorIdx <= targetIdx ? [anchorIdx, targetIdx] : [targetIdx, anchorIdx];
43				const selected = new Set(state.selected);
44				for (let i = lo; i <= hi; i++) {
45					selected.add(orderedIds[i]);
46				}
47				return { selected, anchorId: state.anchorId };
48			}
49		}
50	
51		// Plain click and Cmd/Ctrl click both additive-toggle and re-anchor.
52		const selected = new Set(state.selected);
53		if (selected.has(id)) {
54			selected.delete(id);
55		} else {
56			selected.add(id);
57		}
58		return { selected, anchorId: id };
59	}
60	
61	/** Header checkbox "checked": every visible row is selected (and there are rows). */
62	export function isAllSelected(orderedIds: string[], selected: Set<string>): boolean {
63		return orderedIds.length > 0 && orderedIds.every((id) => selected.has(id));
64	}
65	
66	/** Header checkbox "indeterminate": some — but not all — visible rows are selected. */
67	export function isIndeterminate(orderedIds: string[], selected: Set<string>): boolean {
68		const anySelected = orderedIds.some((id) => selected.has(id));
69		return anySelected && !isAllSelected(orderedIds, selected);
70	}
71	
72	/**
73	 * Header checkbox click: select every visible row, or clear them if all are
74	 * already selected. Selected rows outside the current view are left untouched.
75	 */
76	export function toggleSelectAll(orderedIds: string[], state: SelectionState): SelectionState {
77		const selected = new Set(state.selected);
78		if (isAllSelected(orderedIds, selected)) {
79			for (const id of orderedIds) {
80				selected.delete(id);
81			}
82		} else {
83			for (const id of orderedIds) {
84				selected.add(id);
85			}
86		}
87		return { selected, anchorId: state.anchorId };
88	}
